  p=ROOT/s['best_checkpoint'];assert sha(p)==s['best_checkpoint_sha256'];payload=torch.load(p,map_location='cpu',weights_only=True);assert payload['epoch']==be and payload['config']==cfg and payload['provenance']['classes']==CLASSES;net=timm.create_model(cfg['architecture'],pretrained=False,num_classes=4);net.load_state_dict(payload['state_dict'],strict=True);assert all(torch.isfinite(t).all() for t in payload['state_dict'].values() if t.is_floating_point());del payload,net
  final=ROOT/s.get('prescribed_final_checkpoint',str((run/'checkpoints/last.pt').relative_to(ROOT)));payload=torch.load(final,map_location='cpu',weights_only=True);assert payload['epoch']==stop and payload['control']['stale']==stale and 'optimizer' in payload and 'rng' in payload;assert {'torch','cuda','python','numpy'}<=set(payload['rng']);assert all(torch.isfinite(v).all() for st in payload['optimizer']['state'].values() for v in st.values() if torch.is_tensor(v) and v.is_floating_point());del payload
